#include <iostream>

namespace risk {
    constexpr long long kMaxNotionalCents{1'000'000};   // 1,000,000 cents

    bool withinLimit(long long notionalCents) {
        return notionalCents <= kMaxNotionalCents;
    }
}

int main() {
    std::cout << risk::withinLimit(1'905'000) << '\n';  // 0 - over the cap
    std::cout << risk::withinLimit(950'000) << '\n';    // 1 - inside
    return 0;
}

#include <iostream>
#include <string>

namespace book {
    enum class Side { Buy, Sell };
    enum class Venue : unsigned char { Nyse, Nasdaq, Dark };

    struct Order {
        std::string symbol;
        long long limitCents;
        int quantity;
        Side side;
        Venue venue;
    };

    bool withinLimit(const Order& o, long long capCents) {
        return o.limitCents * static_cast<long long>(o.quantity) <= capCents;
    }
}

