#include <cstdint>
#include <cstdio>
#include <string>

namespace md {                       // namespacing = ownership boundary

enum class Side : uint8_t { Buy, Sell };   // scoped enum: no implicit int leaks

struct OrderId {
    uint64_t value;
    explicit OrderId(uint64_t v) : value(v) {}
};

struct Price {
    int64_t ticks;                    // price as integer ticks: the fix for 0.1+0.2 != 0.3
    explicit Price(int64_t t) : ticks(t) {}
    double as_double(int tick_size_decimals) const {
        double scale = 1; for (int i = 0; i < tick_size_decimals; ++i) scale *= 10;
        return ticks / scale;
    }
};

}  // namespace md

int main() {
    md::Side s = md::Side::Buy;
    // md::Side s2 = 1;                 // COMPILE ERROR: no implicit conversion, which is the point
