guidedExercise.solution:
Notional $= 24850 \times 50 = 1{,}242{,}500$ cents $=$ **\$12,425.00**; the program prints `1242500`.
```cpp
#include <iostream>
#include <string>

struct Price { long long cents; };
struct Order { std::string symbol; Price limit; int quantity; };

long long notionalCents(const Order& o) {
    return o.limit.cents * o.quantity;
}

int main() {
    Order o{"TSLA", {24850}, 50};
    std::cout << notionalCents(o) << '\n';   // 1242500
    return 0;
}
```
The function takes `const Order&` - no copy, no mutation - and integer multiplication keeps the result exact.

independentExercise.solution:
B is larger, so the output is `AAPL 1905000`.
```cpp
#include <iostream>
#include <string>

namespace desk {
    enum class Side { Buy, Sell };

    struct Order {
        std::string symbol;
        long long limitCents;
        int quantity;
        Side side;
    };

    long long notionalCents(const Order& o) {
        return o.limitCents * static_cast<long long>(o.quantity);
    }
}

int main() {
    desk::Order a{"TSLA", 24850, 50, desk::Side::Buy};
    desk::Order b{"AAPL", 19050, 100, desk::Side::Sell};

    const desk::Order& bigger =
        desk::notionalCents(a) > desk::notionalCents(b) ? a : b;
    std::cout << bigger.symbol << ' ' << desk::notionalCents(bigger) << '\n';
    return 0;
}
```
$1{,}242{,}500 < 1{,}905{,}000$, so `bigger` binds to `b` and the program prints `AAPL 1905000` - computed exactly in integer cents.

